function createMascot(p,x=-1,z=1.2){const g=new THREE.Group();g.position.set(x,0,z);p.add(g);const body=ball(g,0,.68,0,.43,.57,.37,"#a6e8d4"),head=ball(g,0,1.53,0,.61,.59,.51,"#fff0e6");const earL=ball(g,-.36,2.04,-.02,.17,.54,.14,"#c6b7ff"),earR=ball(g,.36,2.04,-.02,.17,.54,.14,"#c6b7ff");earL.rotation.z=-.18;earR.rotation.z=.18;ball(g,-.36,2.04,.07,.08,.37,.035,"#ffb8d7").rotation.z=-.18;ball(g,.36,2.04,.07,.08,.37,.035,"#ffb8d7").rotation.z=.18;const eyeL=ball(g,-.2,1.58,.45,.06,.085,.04,"#5e4a67"),eyeR=ball(g,.2,1.58,.45,.06,.085,.04,"#5e4a67"),cheekL=ball(g,-.32,1.39,.43,.11,.065,.035,"#ffb4c9"),cheekR=ball(g,.32,1.39,.43,.11,.065,.035,"#ffb4c9"),nose=ball(g,0,1.43,.49,.05,.04,.025,"#e98eb5");const smile=new THREE.Mesh(new THREE.TorusGeometry(.09,.02,8,16,Math.PI),MAT("#6a4b63"));smile.position.set(0,1.31,.5);smile.rotation.z=Math.PI;g.add(smile);const frown=new THREE.Mesh(new THREE.TorusGeometry(.08,.02,8,16,Math.PI),MAT("#6a4b63"));frown.position.set(0,1.31,.5);g.add(frown);frown.visible=false;const mouth=ball(g,0,1.29,.51,.075,.105,.03,"#6b405b");mouth.visible=false;const armL=ball(g,-.43,.84,.02,.15,.29,.15,"#fff0e6"),armR=ball(g,.43,.84,.02,.15,.29,.15,"#fff0e6");armL.rotation.z=-.48;armR.rotation.z=.48;const footL=ball(g,-.22,.16,.03,.18,.2,.19,"#c6b7ff"),footR=ball(g,.22,.16,.03,.18,.2,.19,"#c6b7ff"),tail=ball(g,.43,.48,-.24,.2,.21,.2,"#ffb8d7");g.userData.parts={body,head,eyeL,eyeR,cheekL,cheekR,smile,frown,mouth,armL,armR,footL,footR,tail,earL,earR};g.userData.home=g.position.clone();g.userData.action={mood:"idle",start:0,duration:0};g.userData.kind="bunny";actorList.push(g);return g}
function createCritter(p,type,x,z){const g=new THREE.Group();g.position.set(x,0,z);p.add(g);const cat=type==="cat",fur=cat?"#f4bfd8":"#d7a177",muzzle=cat?"#fff4ed":"#fff0d7";ball(g,0,.64,0,.43,.53,.37,fur);ball(g,0,1.4,0,.55,.53,.47,cat?"#fff1e8":"#e5b990");if(cat){cone(g,-.32,1.86,0,.18,.45,fur);cone(g,.32,1.86,0,.18,.45,fur)}else{ball(g,-.4,1.78,0,.22,.22,.18,fur);ball(g,.4,1.78,0,.22,.22,.18,fur);ball(g,-.4,1.8,.12,.11,.12,.05,"#ffb8ca");ball(g,.4,1.8,.12,.11,.12,.05,"#ffb8ca")}const eyeL=ball(g,-.18,1.44,.42,.055,.075,.035,"#554658"),eyeR=ball(g,.18,1.44,.42,.055,.075,.035,"#554658");ball(g,0,1.28,.45,.15,.1,.08,muzzle);ball(g,0,1.34,.51,.045,.035,.025,cat?"#dc8fae":"#9a6e64");const smile=new THREE.Mesh(new THREE.TorusGeometry(.08,.018,8,16,Math.PI),MAT("#6a4b63"));smile.position.set(0,1.22,.5);smile.rotation.z=Math.PI;g.add(smile);const frown=new THREE.Mesh(new THREE.TorusGeometry(.075,.018,8,16,Math.PI),MAT("#6a4b63"));frown.position.set(0,1.22,.5);g.add(frown);frown.visible=false;const mouth=ball(g,0,1.2,.51,.07,.09,.03,"#6b405b");mouth.visible=false;const armL=ball(g,-.43,.8,.03,.14,.26,.14,fur),armR=ball(g,.43,.8,.03,.14,.26,.14,fur);armL.rotation.z=-.45;armR.rotation.z=.45;g.userData.parts={eyeL,eyeR,smile,frown,mouth,armL,armR,head};g.userData.home=g.position.clone();g.userData.action={mood:"idle",start:0,duration:0};g.userData.kind=type;actorList.push(g);return g}
function animateActor(a,mood,duration=1.5){if(!a)return;if(!actorList.includes(a))actorList.push(a);a.userData.action={mood,start:clock?clock.getElapsedTime():0,duration};faceActor(a,mood);const s={happy:"cheer",cheer:"cheer",eat:"munch",disgust:"yuck",surprised:"boing",curious:"curious",twirl:"twirl",wave:"sparkle",sad:"yuck",enter:"cheer",bounce:"boing"}[mood];if(s)playSfx(s)}
