const positions={bakery:[-5,-3.5],forest:[0,-5.5],ocean:[5,-3.5],garden:[-5,3.5],dress:[0,5],toy:[5,3.5]};Object.entries(positions).forEach(([key,pos])=>makePortal(root,key,pos[0],pos[1]));
