function startWorld(key){if(!worlds[key])return;worldFinished=false;cooking=false;foundItems=0;dressLooks=new Set();init3D();try{if(document.documentElement.requestFullscreen&&!document.fullscreenElement){const p=document.documentElement.requestFullscreen();if(p&&p.catch)p.catch(()=>{})}}catch(e){}mode="game";currentWorld=key;foundItems=0;ingredients=[];selectedBase="cake";gardenTool="seed";toyPieces=[];accessoryType="";worldRun++;$("mapIntro").style.display="none";$("worldDock").style.display="none";$("mapHint").style.display="none";$("topHud").style.display="none";$("gameHud").classList.add("active");$("gameWorldIcon").textContent=worlds[key].icon;$("gameProgressIcon").textContent=key==="bakery"?"🍰":key==="garden"?"🌷":key==="ocean"?"🫧":"⭐";$("gameProgress").textContent="0";$("recipeDisplay").classList.remove("active");$("rewardOverlay").classList.remove("show");document.querySelectorAll(".tool-shelf").forEach(el=>el.classList.remove("active"));$("commonTools").classList.add("active");buildWorld(key);showWorldLabel(worlds[key].name);playSfx("cheer");}
